<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ArrowLeft, Copy, Pencil, Trash2 } from 'lucide-vue-next'; import AppShell from '@/components/AppShell.vue'; import ConfirmSheet from '@/components/ConfirmSheet.vue'; import { memoryService, type Memory } from '@/services/memory-service'; import { useAppStore } from '@/stores/app'; const route=useRoute(),router=useRouter(),app=useAppStore();const memory=ref<Memory>();const confirm=ref(false);onMounted(async()=>memory.value=await memoryService.get(String(route.params.id)));async function trash(){await memoryService.trash(String(route.params.id));app.showToast('Dipindahkan ke Trash');router.push('/memories')} async function copyMemory(){if(memory.value){await window.navigator.clipboard.writeText(memory.value.content);app.showToast('Disalin')}}</script>
<template><AppShell><div class="page"><button class="icon-button -ml-3" aria-label="Kembali" @click="$router.back()"><ArrowLeft /></button><div v-if="memory" class="pt-7"><div class="flex items-start justify-between gap-5"><div><p class="text-sm font-medium text-nemu-600 dark:text-[#83d8b2]">{{ memory.category }}</p><h1 class="mt-2 text-3xl font-semibold tracking-[-.035em]">{{ memory.title }}</h1></div><RouterLink :to="`/memories/${memory.id}/edit`" class="icon-button border border-line"><Pencil :size="18" /></RouterLink></div><article class="surface mt-8 rounded-3xl border border-line p-6"><p class="whitespace-pre-wrap text-[16px] leading-7">{{ memory.content }}</p></article><dl class="mt-7 grid grid-cols-2 gap-y-5 text-sm"><div><dt class="text-muted">Disimpan</dt><dd class="mt-1 font-medium">{{ memory.createdAt }}</dd></div><div><dt class="text-muted">Terakhir diubah</dt><dd class="mt-1 font-medium">{{ memory.updatedAt }}</dd></div><div><dt class="text-muted">Sumber</dt><dd class="mt-1 font-medium">Manual</dd></div></dl><div class="mt-10 flex gap-3"><button class="soft-button flex-1" @click="copyMemory"><Copy :size="17" />Copy</button><button class="flex min-h-12 flex-1 items-center justify-center gap-2 rounded-2xl border border-red-200 px-4 text-sm font-semibold text-red-600 dark:border-red-900" @click="confirm=true"><Trash2 :size="17" />Delete</button></div></div></div><ConfirmSheet :open="confirm" :title="`Hapus memory '${memory?.title ?? ''}'?`" description="Memory akan dipindahkan ke Trash dan dapat dipulihkan." action="Move to Trash" @close="confirm=false" @confirm="trash" /></AppShell></template>
